use onisim_gpu::multicomponent::{cpu_step,MulticomponentGpu,State};
use serde::Serialize;use std::time::Instant;
struct Fixture{mass:Vec<f32>,vx:Vec<f32>,vy:Vec<f32>,solid:Vec<u32>,drift:Vec<f32>}
impl Fixture{fn new(w:usize,h:usize,c:usize)->Self{let n=w*h;let mut s=0x12345678u32;let mut r=||{s^=s<<13;s^=s>>17;s^=s<<5;s};let mut solid=vec![0;n];for x in 0..w{solid[x]=1;solid[(h-1)*w+x]=1;}for y in 0..h{solid[y*w]=1;solid[y*w+w-1]=1;}if w>16&&h>16{for y in h/3..h/3+7{for x in w/3..w/3+11{solid[y*w+x]=1;}}}let mut mass=(0..n*c).map(|_|(r()%10000)as f32/10000.0).collect::<Vec<_>>();for i in 0..n{if solid[i]!=0{mass[i*c..(i+1)*c].fill(0.0);}}let vx=(0..n).map(|_|((r()%2001)as i32-1000)as f32*0.00002).collect();let vy=(0..n).map(|_|((r()%2001)as i32-1000)as f32*0.00002).collect();let drift=(0..c).map(|i|(i as f32-(c as f32-1.0)*0.5)*0.0001).collect();Self{mass,vx,vy,solid,drift}}fn state(&self)->State<'_>{State{mass:&self.mass,velocity_x:&self.vx,velocity_y:&self.vy,solid:&self.solid,drift_y:&self.drift}}}
#[derive(Serialize)]struct Row{width:usize,height:usize,channels:usize,cpu_median_us:f64,gpu_upload_dispatch_sync_readback_median_us:f64,gpu_resident_32_steps_total_us:f64,gpu_resident_per_step_us:f64,max_abs_error:f64,max_relative_error:f64,mass_relative_error:f64,nonnegative:bool,solid_zero:bool}
#[derive(Serialize)]struct Report{stage:&'static str,adapter:String,vendor:u32,device_type:String,backend:String,warmup:usize,samples:usize,results:Vec<Row>}
fn median(v:&mut[f64])->f64{v.sort_by(f64::total_cmp);v[v.len()/2]}
fn main()->Result<(),String>{let mut rows=Vec::new();let(mut adapter,mut vendor,mut kind,mut backend)=(String::new(),0,String::new(),String::new());for(w,h,c)in[(96,96,4),(256,384,4)]{let f=Fixture::new(w,h,c);let state=f.state();let n=w*h*c;let dt=0.02;let mut cpu=vec![0.0;n];let mut gpu_out=vec![0.0;n];cpu_step(&state,w,h,c,dt,&mut cpu);let mut gpu=pollster::block_on(MulticomponentGpu::new(w,h,c))?;adapter=gpu.adapter.name.clone();vendor=gpu.adapter.vendor;kind=format!("{:?}",gpu.adapter.device_type);backend=format!("{:?}",gpu.adapter.backend);gpu.upload(&state)?;gpu.run_steps_and_readback(1,dt,&mut gpu_out)?;let mut abs=0.0f64;let mut rel=0.0f64;for(&a,&b)in cpu.iter().zip(&gpu_out){let e=(a as f64-b as f64).abs();abs=abs.max(e);rel=rel.max(e/(a as f64).abs().max(1e-8));}let mut sums=[0.0f64;4];let mut outs=[0.0f64;4];for cell in 0..w*h{for k in 0..c.min(4){sums[k]+=cpu[cell*c+k]as f64;outs[k]+=gpu_out[cell*c+k]as f64;}}let mass_error=(0..c.min(4)).map(|k|(sums[k]-outs[k]).abs()/sums[k].abs().max(1e-30)).fold(0.0,f64::max);let nonnegative=gpu_out.iter().all(|v|*v>=-1e-7);let solid_zero=(0..w*h).all(|i|f.solid[i]==0||gpu_out[i*c..(i+1)*c].iter().all(|v|*v==0.0));if rel>1e-5||!nonnegative||!solid_zero{return Err(format!("parity gate failed {w}x{h}x{c}, max rel {rel:e}"));}let mut ct=Vec::new();let mut et=Vec::new();let mut rt=Vec::new();for _ in 0..5{gpu.upload(&state)?;gpu.run_steps_and_readback(1,dt,&mut gpu_out)?;gpu.upload(&state)?;gpu.run_steps_and_readback(32,dt,&mut gpu_out)?;}for _ in 0..31{let t=Instant::now();cpu_step(&state,w,h,c,dt,&mut cpu);ct.push(t.elapsed().as_secs_f64()*1e6);let t=Instant::now();gpu.upload(&state)?;gpu.run_steps_and_readback(1,dt,&mut gpu_out)?;et.push(t.elapsed().as_secs_f64()*1e6);let t=Instant::now();gpu.upload(&state)?;gpu.run_steps_and_readback(32,dt,&mut gpu_out)?;rt.push(t.elapsed().as_secs_f64()*1e6);}let cpu_us=median(&mut ct);let e2e=median(&mut et);let resident=median(&mut rt);rows.push(Row{width:w,height:h,channels:c,cpu_median_us:cpu_us,gpu_upload_dispatch_sync_readback_median_us:e2e,gpu_resident_32_steps_total_us:resident,gpu_resident_per_step_us:resident/32.0,max_abs_error:abs,max_relative_error:rel,mass_relative_error:mass_error,nonnegative,solid_zero});}println!("{}",serde_json::to_string_pretty(&Report{stage:"Stage 1 Vulkan operator acceptance",adapter,vendor,device_type:kind,backend,warmup:5,samples:31,results:rows}).map_err(|e|e.to_string())?);Ok(())}
